import java.util.*;
class CacheModel {record Value(int value,int version){}static class Entry{int value,version,expires;boolean dirty;Entry(int v,int ver,int exp,boolean d){value=v;version=ver;expires=exp;dirty=d;}}record Op(String kind,String key,int value){}final Map<String,Value>db=new HashMap<>(Map.of("a",new Value(1,0),"b",new Value(2,0)));final LinkedHashMap<String,Entry>cache=new LinkedHashMap<>();final List<Integer>reads=new ArrayList<>();int lost;
void flush(String k,Entry e){if(e.dirty){db.put(k,new Value(e.value,e.version));e.dirty=false;}}void put(String k,Entry e,int capacity){cache.remove(k);if(cache.size()>=capacity){var old=cache.entrySet().iterator().next();flush(old.getKey(),old.getValue());cache.remove(old.getKey());}cache.put(k,e);}
void run(List<Op> ops,String strategy,int capacity,int ttl,boolean loseInvalidation){for(int tick=0;tick<ops.size();tick++){for(var it=cache.entrySet().iterator();it.hasNext();){var e=it.next();if(e.getValue().expires<=tick){flush(e.getKey(),e.getValue());it.remove();}}Op op=ops.get(tick);String k=op.key();if(op.kind().equals("read")){Entry e=cache.remove(k);if(e!=null)cache.put(k,e);else if(db.containsKey(k)){Value v=db.get(k);e=new Entry(v.value(),v.version(),tick+ttl,false);put(k,e,capacity);}reads.add(e==null?null:e.value);}
else if(op.kind().equals("write")){int version=Math.max(db.containsKey(k)?db.get(k).version():0,cache.containsKey(k)?cache.get(k).version:0)+1;if(strategy.equals("write-back"))put(k,new Entry(op.value(),version,tick+ttl,true),capacity);else{db.put(k,new Value(op.value(),version));if(strategy.equals("write-through"))put(k,new Entry(op.value(),version,tick+ttl,false),capacity);else if(!loseInvalidation)cache.remove(k);}}
else if(op.kind().equals("invalidate")){if(cache.containsKey(k))flush(k,cache.get(k));cache.remove(k);}else if(op.kind().equals("crash")){lost+=cache.values().stream().filter(e->e.dirty).count();cache.clear();}}}}

